<template>
  <figure ref="figure" class="gallery-live-demo index-ignore" :class="{ 'is-phone': phone || portrait, 'is-portrait': portrait, 'is-responsive-journey': kind === 'responsive', 'is-compact-presentation': compact }">
    <header v-if="!compact && kind !== 'responsive'">
      <div>
        <span v-if="kind !== 'responsive'">{{ eyebrow }}</span>
        <h4>{{ title }}</h4>
      </div>
      <a :href="fullUrl" target="_blank" rel="noopener">Open full Gallery <span aria-hidden="true">↗</span></a>
    </header>
    <p v-if="kind === 'responsive'" class="gallery-live-device-label">{{ portrait ? 'Portrait' : 'Landscape' }}</p>
    <div ref="stage" class="gallery-live-stage" :style="stageStyle">
      <iframe
        v-if="mountedFrame"
        ref="frame"
        :key="frameKey"
        :src="frameUrl"
        :title="title"
        :style="frameStyle"
        tabindex="-1"
        allow="autoplay 'none'; fullscreen"
        @load="onFrameLoad"
      ></iframe>
      <div v-else class="gallery-live-placeholder" aria-hidden="true">
        <span></span><span></span><span></span>
      </div>
    </div>
    <figcaption v-if="kind !== 'responsive'">
      <p>{{ description }}</p>
      <div class="gallery-live-actions">
        <a v-if="compact" :href="fullUrl" target="_blank" rel="noopener">Open Gallery <span aria-hidden="true">↗</span></a>
        <button v-if="mountedFrame && kind !== 'responsive'" class="gallery-live-transport" type="button" :aria-label="localPaused ? 'Continue demonstration' : 'Pause demonstration'" @click="localPaused = !localPaused">
          <svg viewBox="0 0 20 20" aria-hidden="true"><path v-if="localPaused" d="m7 4 8 6-8 6Z"/><path v-else d="M7 4v12M13 4v12"/></svg>
        </button>
      </div>
    </figcaption>
  </figure>
</template>

<script>
export default {
  name: 'ViewGalleryLiveDemo',
  props: {
    kind: { type: String, validator: value => ['tour', 'walkthrough', 'responsive'].includes(value), required: true },
    phone: Boolean,
    portrait: Boolean,
    compact: Boolean,
    enabled: { type: Boolean, default: true },
    responsivePhase: { type: String, validator: value => ['gallery', 'exhibition'].includes(value), default: '' },
    paused: Boolean,
  },
  data: () => ({ visible: false, playbackVisible: false, pageVisible: true, frameKey: 0, scale: 1, phase: 0, localPaused: false }),
  computed: {
    mountedFrame() { return this.enabled && this.visible; },
    activeKind() {
      if (this.kind !== 'responsive') return this.kind;
      if (this.responsivePhase) return this.responsivePhase === 'exhibition' ? 'walkthrough' : 'tour';
      return this.phase % 2 ? 'walkthrough' : 'tour';
    },
    baseSize() { return this.portrait ? { width: 390, height: 844 } : this.phone ? { width: 844, height: 390 } : { width: 1440, height: 900 }; },
    frameUrl() {
      const path = this.activeKind === 'tour' ? '/views' : '/view/PNZPdB__yBeyYjkF';
      const controls = this.phone || this.portrait ? '&showcaseControls=1' : '';
      return `${window.location.pathname}#${path}?showcase=${this.activeKind}&galleryFrame=1${controls}&showcaseChannel=${this.channel}`;
    },
    fullUrl() {
      const path = this.kind === 'tour' ? '/views' : '/view/PNZPdB__yBeyYjkF';
      return `${window.location.pathname}#${path}?presentation=museum&temporaryPresentation=1`;
    },
    eyebrow() { return this.portrait ? 'Phone portrait' : this.phone ? 'Phone landscape' : 'Desktop'; },
    title() {
      if (this.kind === 'responsive') return `${this.portrait ? 'Portrait' : 'Landscape'} ${this.activeKind === 'tour' ? 'Gallery' : 'Exhibition'} demonstration`;
      return this.kind === 'tour' ? 'Gallery in motion' : 'Following a View through the exhibition';
    },
    channel() { return `gallery-live-${this.$.uid}`; },
    effectivePaused() { return (this.kind === 'responsive' ? this.paused : this.localPaused) || !this.playbackVisible || !this.pageVisible; },
    description() {
      if (this.kind === 'responsive') return this.portrait
        ? 'A reading sheet and touch controls preserve the room within a narrow screen.'
        : 'The room and narrative share the wider phone canvas, with its controls kept in view.';
      return this.kind === 'tour'
        ? 'A live demo moving through the hall, collection, entrance, composition desk and pavilion note.'
        : 'A generated View becomes a sequence of rooms where its narrative and original sources remain together.';
    },
    stageStyle() { return { height: `${this.baseSize.height * this.scale}px` }; },
    frameStyle() { return { width: `${this.baseSize.width}px`, height: `${this.baseSize.height}px`, transform: `scale(${this.scale})` }; },
  },
  watch: {
    enabled(value) { if (value) this.observe(); },
    responsivePhase() {
      if (this.kind !== 'responsive') return;
      clearTimeout(this._phaseTimer);
      this.frameKey += 1;
    },
    paused() { this.sendPlaybackState(); },
    localPaused() { this.sendPlaybackState(); },
    playbackVisible() { this.sendPlaybackState(); },
    pageVisible() { this.sendPlaybackState(); },
  },
  mounted() {
    this._resize = new ResizeObserver(this.measure);
    this._resize.observe(this.$refs.stage);
    this._playbackObserver = new IntersectionObserver(entries => {
      this.playbackVisible = Boolean(entries[0]?.isIntersecting && entries[0].intersectionRatio >= .25);
    }, { threshold: [0, .25] });
    this._playbackObserver.observe(this.$refs.stage);
    this._visibility = () => { this.pageVisible = !document.hidden; };
    this._visibility();
    document.addEventListener('visibilitychange', this._visibility);
    this.observe();
  },
  beforeUnmount() { this._observer?.disconnect(); this._playbackObserver?.disconnect(); this._resize?.disconnect(); document.removeEventListener('visibilitychange', this._visibility); clearTimeout(this._phaseTimer); },
  methods: {
    observe() {
      if (!this.enabled || this.visible || this._observer) return;
      this._observer = new IntersectionObserver(entries => {
        if (!entries.some(entry => entry.isIntersecting)) return;
        this.visible = true;
        this._observer.disconnect();
        this._observer = null;
      }, { rootMargin: '220px 0px' });
      this._observer.observe(this.$refs.figure);
    },
    measure() {
      const width = this.$refs.stage?.clientWidth || this.baseSize.width;
      this.scale = this.kind === 'responsive' ? width / this.baseSize.width : Math.min(1, width / this.baseSize.width);
    },
    onFrameLoad() {
      this.sendPlaybackState();
      this.schedulePhase();
    },
    schedulePhase() {
      if (this.kind !== 'responsive') return;
      if (this.responsivePhase) return;
      clearTimeout(this._phaseTimer);
      this._phaseTimer = setTimeout(() => { this.phase += 1; this.frameKey += 1; }, this.activeKind === 'tour' ? 18500 : 24000);
    },
    sendPlaybackState() {
      this.$refs.frame?.contentWindow?.postMessage({ type: 'view-gallery-showcase-playback', channel: this.channel, paused: this.effectivePaused }, window.location.origin);
    },
    restart() { clearTimeout(this._phaseTimer); this.phase = 0; this.frameKey += 1; },
  },
};
</script>

