.gallery-live-device-label{margin:0 0 .65rem;color:var(--site-text-primary);font:400 .68rem/1.35 "Quattrocento Sans",sans-serif;letter-spacing:.08em;text-align:center;text-transform:uppercase}
.gallery-live-actions a{position:relative}.gallery-live-actions a::after{content:"";position:absolute;left:0;right:1rem;bottom:-.22rem;height:1px;background:currentColor;transform:scaleX(0);transform-origin:right;transition:transform 220ms cubic-bezier(.22,1,.36,1)}
