@media(max-width:700px){.gallery-live-demo>header{align-items:start}.gallery-live-demo>header a{font-size:.7rem}.gallery-live-demo figcaption:not(.is-device-label){display:block}.gallery-live-demo figcaption button{margin-top:.7rem}}
@media(hover:hover) and (pointer:fine){.gallery-live-demo>header a:hover span{transform:translate(2px,-2px)}.gallery-live-actions a:hover::after{transform:scaleX(1);transform-origin:left}.gallery-live-actions a:hover span{transform:translate(2px,-2px)}.gallery-live-transport:hover{background:color-mix(in srgb,currentColor 10%,transparent);color:var(--site-text-primary)}}
@media(prefers-reduced-motion:reduce){.gallery-live-placeholder span{animation:none}.gallery-live-demo>header a span,.gallery-live-stage{transition:none}}
</style>
