<template>
  <div ref="viewport" class="demo-screen-viewport" :class="{ 'is-phone': compact }" aria-hidden="true" inert>
    <iframe v-if="active" ref="frame" src="/archive-preview.html" :title="compact ? 'Phone preview' : 'Desktop preview'" tabindex="-1" :style="{ width: `${width}px`, height: `${height}px`, transform: `scale(${scale})`, borderRadius: compact ? `${19 / scale}px` : '0', clipPath: compact ? `inset(0 round ${19 / scale}px)` : 'none' }" />
    <video v-if="active && scene==='home'" v-show="galleryVisible" ref="gallery" class="demo-gallery-result" :src="compact?'/assets/video/view-gallery/arrival-portrait.mp4':'/assets/video/view-gallery/arrival-desktop.mp4'" muted playsinline preload="metadata" @loadedmetadata="syncGallery(true)" />
  </div>
</template>
<script>
export default {
  name: 'ArchiveDemoScreen',
  props: { active: Boolean, compact: Boolean, device: String, scene: String, state: Object, playing: Boolean, reducedMotion: Boolean },
  emits: ['ready'],
  data: () => ({ scale: 1, ready: false, dark: false }),
  computed: {
    width() { return this.compact ? 390 : 1440; },
    height() { return this.compact ? 780 : 920; },
    galleryVisible() { return this.scene==='home'&&this.state?.phase==='reading'; },
    galleryTime() { return 36.2+Math.max(0,(Number(this.state?.time)||12400)-12400)/1000; },
  },
  watch: { state() { this.sendFrame();this.syncGallery(); }, playing() { this.sendFrame(true);this.syncGallery(); }, galleryVisible() { this.$nextTick(()=>this.syncGallery(true)); }, dark() { this.sendFrame(true); }, scale() { this.sendFrame(true); }, device() { this.$nextTick(() => this.sendFrame(true)); } },
  mounted() {
    const resize = entries => {
      const width = entries?.[0]?.contentRect.width ?? parseFloat(getComputedStyle(this.$refs.viewport).width);
      if (width > 0) this.scale = width / this.width;
    };
    this._resize = new ResizeObserver(resize); this._resize.observe(this.$refs.viewport); resize();
    this._onMessage = event => {
      if (event.source !== this.$refs.frame?.contentWindow || event.origin !== location.origin || event.data?.type !== 'archive-preview-ready') return;
      this.ready = true; this.sendFrame(true); this.$emit('ready');
    };
    window.addEventListener('message', this._onMessage);
    const syncTheme = () => { this.dark = document.body.classList.contains('dark-mode'); };
    this._theme = new MutationObserver(syncTheme); this._theme.observe(document.body, { attributes: true, attributeFilter: ['class'] }); syncTheme();
  },
  beforeUnmount() { this._resize?.disconnect(); this._theme?.disconnect(); window.removeEventListener('message', this._onMessage); },
  methods: {
    sendFrame(force = false) {
      if (!this.ready) return;
      const now = performance.now();
      if (!force && now - (this._lastSent || 0) < 30) return;
      this._lastSent = now;
      this.$refs.frame.contentWindow.postMessage({ type: 'archive-preview-frame', scene: this.scene, elapsed: this.state.time, playing: this.playing, dark: this.dark, reducedMotion: this.reducedMotion, cornerRadius: this.compact ? 19 / this.scale : 0 }, location.origin);
    },
    syncGallery(force=false){
      const video=this.$refs.gallery;if(!video||!Number.isFinite(video.duration))return;
      const target=Math.min(Math.max(0,video.duration-.05),this.galleryTime);
      if(force||Math.abs(video.currentTime-target)>.28)video.currentTime=target;
      if(this.galleryVisible&&this.playing&&!this.reducedMotion)video.play().catch(()=>{});else video.pause();
    },
  },
};
</script>
<style scoped>
.demo-screen-viewport { position:relative; width:100%; aspect-ratio:1440/920; overflow:hidden; background:var(--demo-paper,#fff); pointer-events:none; user-select:none; }
.demo-screen-viewport.is-phone { aspect-ratio:390/780; }
iframe { position:absolute; top:0; left:0; border:0; transform-origin:top left; pointer-events:none; }
.demo-gallery-result { position:absolute; z-index:2; inset:0; display:block; width:100%; height:100%; object-fit:cover; background:#201e1c; pointer-events:none; animation:demo-gallery-arrive 520ms cubic-bezier(.22,1,.36,1) both; }
@keyframes demo-gallery-arrive { from { opacity:0; transform:scale(1.012); } to { opacity:1; transform:none; } }
@media(prefers-reduced-motion:reduce){.demo-gallery-result{animation:none}}
</style>
