            <div ref="exhibitionStage" class="view-journey-frame">
              <iframe v-if="mountedFrames" ref="exhibitionFrame" :src="exhibitionUrl" title="The same View moving through its exhibition presentation" :style="exhibitionFrameStyle" tabindex="-1" allow="autoplay 'none'; fullscreen" @load="sendPlaybackState"></iframe>
              <div v-else class="view-journey-placeholder" aria-hidden="true"><i></i><i></i><i></i></div>
