  },
  watch: {
    enabled(value) { if (value && !this.visible) this._observer?.observe(this.$refs.figure); },
    paused() { this.sendPlaybackState(); }, playbackVisible() { this.sendPlaybackState(); }, pageVisible() { this.sendPlaybackState(); },
  },
  mounted() {
    this._resize = new ResizeObserver(this.measure); this._resize.observe(this.$refs.articleStage); this._resize.observe(this.$refs.exhibitionStage);
