    if (this.enabled) this._observer.observe(this.$refs.figure);
    this._playbackObserver = new IntersectionObserver(entries => { this.playbackVisible = Boolean(entries[0]?.isIntersecting && entries[0].intersectionRatio >= .25); }, { threshold: [0, .25] });
    this._playbackObserver.observe(this.$refs.figure);
    this._visibility = () => { this.pageVisible = !document.hidden; }; this._visibility(); document.addEventListener('visibilitychange', this._visibility);
    this._onScroll = () => { if (this._morphFrame) return; this._morphFrame = requestAnimationFrame(() => { this._morphFrame = 0; this.syncMorph(); }); };
    window.addEventListener('scroll', this._onScroll, { passive: true }); window.addEventListener('resize', this._onScroll, { passive: true }); window.addEventListener('message', this.forwardPosition);
    this.$nextTick(this.syncMorph);
  },
  beforeUnmount() {
    this._observer?.disconnect(); this._playbackObserver?.disconnect(); this._resize?.disconnect(); cancelAnimationFrame(this._morphFrame);
    document.removeEventListener('visibilitychange', this._visibility); window.removeEventListener('scroll', this._onScroll); window.removeEventListener('resize', this._onScroll); window.removeEventListener('message', this.forwardPosition);
  },
  methods: {
    frameStyle(scale) { return { width: `${BASE.width}px`, height: `${BASE.height}px`, transform: `scale(${scale})` }; },
    syncMorph() {
      const element = this.$refs.scroll;
      if (!element || window.matchMedia('(max-width: 760px)').matches) { this.morphProgress = 1; return; }
      const rect = element.getBoundingClientRect();
      const stickyHeight = this.$refs.sticky?.offsetHeight || Math.min(window.innerHeight * .66, 660);
      const stickyTop = parseFloat(window.getComputedStyle(this.$refs.sticky).top) || 0;
      const travel = Math.max(1, element.offsetHeight - stickyHeight - stickyTop);
      const hold = Math.min(window.innerHeight * .55, travel * .45);
      const morphTravel = Math.max(1, travel - hold);
      this.morphProgress = Math.max(0, Math.min(1, -rect.top / morphTravel)); if (this.morphProgress <= .72 && this.focus) this.focus = '';
    },
    measure() { this.articleScale = Math.min(1, (this.$refs.articleStage?.clientWidth || BASE.width) / BASE.width); this.exhibitionScale = Math.min(1, (this.$refs.exhibitionStage?.clientWidth || BASE.width) / BASE.width); },
    forwardPosition(event) {
