      this.$refs.articleFrame?.contentWindow?.postMessage(message, window.location.origin); this.$refs.exhibitionFrame?.contentWindow?.postMessage(message, window.location.origin);
    },
    toggleFocus(kind) { if (this.morphProgress <= .72) return; this.focus = this.focus === kind ? '' : kind; this.$nextTick(this.measure); },
  },
};
</script>

